// utilref: prints the behaviour of the upstream (Go) utilities.go and precedence.go functions.
// Reference for test/ts/ast/UtilitiesGolden.hx (golden file test/ts/ast/utilities.golden.txt).
// Built against the pinned upstream with `go build -overlay` (see tools/gen/ast/goref/utilref.sh);
// upstream files are not changed. The function tables (funcs.go, and the Haxe twin
// test/ts/ast/UtilitiesGoldenTable.hx) are generated by ./gen from the upstream sources.
//
// Output:
//   kfuncs <names>                     header of the kind section
//   kind <k> <values>                  every func(Kind) for Kind -1 .. KindCount+1
//   opk <k> <v0> <v1> <v2> <v3>        GetOperatorPrecedence(k, k, flags 0..3) for every kind
//   opb <nodeKind> <flags> <values>    GetOperatorPrecedence(nodeKind, op, flags) for op 0 .. KindCount-1
//   nfuncs <names>                     header of the node section
//   case <factory case header>         as in factory.golden.txt (same enumeration and arguments)
//   free n <values>                    every node function on the node without parent
//   tree <target> <values>             the node (rebuilt) in Block > ExpressionStatement > node with
//                                      SetParentInChildren(block); target n and each direct child
// Fields are separated by tabs. Values: bool 1/0, ints as int32, strings quoted, nodes by label
// (n, stmt, block, p<i>, p<i>.<j>, ?Kind for unlabelled, nil), node slices as [a,b] or nil;
// "panic" when the function panics, "badcast" when it panics in a failed As*() cast (the Haxe
// casts are unchecked, PORTING.md 3b, so the replay accepts any result there).
package main

import (
	"fmt"
	"reflect"
	"runtime"
	"sort"
	"strings"

	"github.com/microsoft/typescript-go/internal/ast"
)

var kindChoices = map[string][]ast.Kind{
	"NewToken":                       {ast.KindAsyncKeyword, ast.KindQuestionDotToken, ast.KindThisKeyword, ast.KindUsingKeyword, ast.KindPublicKeyword, ast.KindAsteriskAsteriskToken, ast.KindCommaToken},
	"NewModifier":                    {ast.KindExportKeyword},
	"NewForInOrOfStatement":          {ast.KindForInStatement, ast.KindForOfStatement},
	"NewCaseOrDefaultClause":         {ast.KindCaseClause, ast.KindDefaultClause},
	"NewBindingPattern":              {ast.KindObjectBindingPattern, ast.KindArrayBindingPattern},
	"NewHeritageClause":              {ast.KindExtendsKeyword, ast.KindImplementsKeyword},
	"NewKeywordExpression":           {ast.KindThisKeyword, ast.KindSuperKeyword, ast.KindNullKeyword},
	"NewPrefixUnaryExpression":       {ast.KindPlusPlusToken, ast.KindExclamationToken},
	"NewPostfixUnaryExpression":      {ast.KindMinusMinusToken},
	"NewMetaProperty":                {ast.KindImportKeyword, ast.KindNewKeyword},
	"NewKeywordTypeNode":             {ast.KindAnyKeyword},
	"NewTypeOperatorNode":            {ast.KindKeyOfKeyword},
	"NewImportAttributes":            {ast.KindWithKeyword},
	"NewModuleDeclaration":           {ast.KindNamespaceKeyword},
	"NewImportClause":                {ast.KindTypeKeyword, ast.KindUnknown},
	"NewJSDocParameterOrPropertyTag": {ast.KindJSDocParameterTag, ast.KindJSDocPropertyTag},
}

const (
	nodeFlagsArg  = ast.NodeFlagsOptionalChain | ast.NodeFlagsLet
	tokenFlagsArg = ast.TokenFlagsUnterminated | ast.TokenFlagsScientific | ast.TokenFlagsContainsInvalidEscape | ast.TokenFlagsSingleQuote | ast.TokenFlagsHexSpecifier
)

type labels map[*ast.Node]string

func (l labels) of(n *ast.Node) string {
	if n == nil {
		return "nil"
	}
	if s, ok := l[n]; ok {
		return s
	}
	return "?" + n.Kind.String()
}

func (l labels) list(ns []*ast.Node) string {
	if ns == nil {
		return "nil"
	}
	parts := make([]string, len(ns))
	for i, n := range ns {
		parts[i] = l.of(n)
	}
	return "[" + strings.Join(parts, ",") + "]"
}

func fb(b bool) string {
	if b {
		return "1"
	}
	return "0"
}

func fi(i int32) string { return fmt.Sprint(i) }

// The internal symbol name prefix (Go "\xFE", Haxe "\u{FFFE}") is printed as the text \xFE.
func fs(s string) string { return "\"" + strings.ReplaceAll(s, "\xFE", `\xFE`) + "\"" }

func safe(f func() string) (result string) {
	defer func() {
		if r := recover(); r != nil {
			result = "panic"
			// A failed As*() cast (Go type assertion). The Haxe As*() casts are unchecked
			// (PORTING.md 3b): the replay accepts any result for these.
			if _, ok := r.(*runtime.TypeAssertionError); ok {
				result = "badcast"
			}
		}
	}()
	return f()
}

var operatorFlagNodeKinds = []ast.Kind{
	ast.KindBinaryExpression, ast.KindPrefixUnaryExpression, ast.KindPostfixUnaryExpression, ast.KindNewExpression,
	ast.KindCallExpression, ast.KindPropertyAccessExpression, ast.KindElementAccessExpression,
}

func main() {
	fmt.Printf("kfuncs\t%s\n", strings.Join(kindFuncNames, "\t"))
	for k := -1; k <= int(ast.KindCount)+1; k++ {
		vals := make([]string, len(kindFuncs))
		for i, f := range kindFuncs {
			vals[i] = safe(func() string { return f(ast.Kind(k)) })
		}
		fmt.Printf("kind\t%d\t%s\n", k, strings.Join(vals, "\t"))
	}
	for k := -1; k <= int(ast.KindCount)+1; k++ {
		vals := make([]string, 4)
		for flags := range 4 {
			vals[flags] = safe(func() string {
				return fi(int32(ast.GetOperatorPrecedence(ast.Kind(k), ast.Kind(k), ast.OperatorPrecedenceFlags(flags))))
			})
		}
		fmt.Printf("opk\t%d\t%s\n", k, strings.Join(vals, "\t"))
	}
	for _, nk := range operatorFlagNodeKinds {
		for flags := range 3 {
			vals := make([]string, int(ast.KindCount))
			for op := range int(ast.KindCount) {
				vals[op] = safe(func() string {
					return fi(int32(ast.GetOperatorPrecedence(nk, ast.Kind(op), ast.OperatorPrecedenceFlags(flags))))
				})
			}
			fmt.Printf("opb\t%d\t%d\t%s\n", int(nk), flags, strings.Join(vals, "\t"))
		}
	}

	fmt.Printf("nfuncs\t%s\n", strings.Join(nodeFuncNames, "\t"))
	ft := reflect.TypeOf(&ast.NodeFactory{})
	var names []string
	for i := range ft.NumMethod() {
		name := ft.Method(i).Name
		if strings.HasPrefix(name, "New") && name != "NewNodeList" && name != "NewModifierList" && name != "NewSourceFile" && name != "NewCommentRange" {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	for _, name := range names {
		m, _ := ft.MethodByName(name)
		var types []string
		hasBool := false
		for i := 1; i < m.Type.NumIn(); i++ {
			t := m.Type.In(i).String()
			if t == "interface {}" {
				t = "any"
			}
			types = append(types, t)
			if t == "bool" {
				hasBool = true
			}
		}
		kinds := kindChoices[name]
		if len(kinds) == 0 {
			kinds = []ast.Kind{ast.KindUnknown}
		}
		bools := []bool{true}
		if hasBool {
			bools = []bool{true, false}
		}
		for _, kind := range kinds {
			for _, b := range bools {
				runCase(name, types, kind, b)
			}
		}
	}
}

// buildCase builds the node of a factory case like tools/gen/ast/goref/main.go (children are
// identifiers "c<i>" labelled by parameter: "p3" (node), "p3.1" (list element)).
func buildCase(name string, types []string, kind ast.Kind, boolValue bool) (*ast.Node, labels) {
	childFactory := ast.NewNodeFactory(ast.NodeFactoryHooks{})
	f := ast.NewNodeFactory(ast.NodeFactoryHooks{})
	lb := labels{}
	counter := 0
	newChild := func(label string) *ast.Node {
		counter++
		c := childFactory.NewIdentifier(fmt.Sprintf("c%d", counter))
		lb[c] = label
		return c
	}
	var args []reflect.Value
	for i, t := range types {
		p := fmt.Sprintf("p%d", i)
		switch t {
		case "*ast.Node":
			args = append(args, reflect.ValueOf(newChild(p)))
		case "*ast.NodeList":
			args = append(args, reflect.ValueOf(childFactory.NewNodeList([]*ast.Node{newChild(p + ".0"), newChild(p + ".1")})))
		case "*ast.ModifierList":
			m0 := childFactory.NewToken(ast.KindExportKeyword)
			m1 := childFactory.NewToken(ast.KindAsyncKeyword)
			lb[m0] = p + ".0"
			lb[m1] = p + ".1"
			args = append(args, reflect.ValueOf(childFactory.NewModifierList([]*ast.Node{m0, m1})))
		case "[]*ast.Node":
			args = append(args, reflect.ValueOf([]*ast.Node{newChild(p + ".0"), newChild(p + ".1")}))
		case "[]string":
			args = append(args, reflect.ValueOf([]string{p + "a", p + "b"}))
		case "string":
			args = append(args, reflect.ValueOf("s"+p))
		case "bool":
			args = append(args, reflect.ValueOf(boolValue))
		case "int":
			args = append(args, reflect.ValueOf(7))
		case "ast.Kind":
			args = append(args, reflect.ValueOf(kind))
		case "ast.NodeFlags":
			args = append(args, reflect.ValueOf(nodeFlagsArg))
		case "ast.TokenFlags":
			args = append(args, reflect.ValueOf(tokenFlagsArg))
		case "any":
			args = append(args, reflect.Zero(reflect.TypeOf((*any)(nil)).Elem()))
		default:
			panic("unhandled param type " + t)
		}
	}
	node := reflect.ValueOf(f).MethodByName(name).Call(args)[0].Interface().(*ast.Node)
	lb[node] = "n"
	return node, lb
}

func evalAll(n *ast.Node, lb labels) string {
	vals := make([]string, len(nodeFuncs))
	for i, f := range nodeFuncs {
		vals[i] = safe(func() string { return f(n, lb) })
	}
	return strings.Join(vals, "\t")
}

func runCase(name string, types []string, kind ast.Kind, boolValue bool) {
	bi := 0
	if boolValue {
		bi = 1
	}
	fmt.Printf("case %s %s %d %d\n", name, strings.Join(types, ","), int(kind), bi)

	node, lb := buildCase(name, types, kind, boolValue)
	fmt.Printf("free\tn\t%s\n", evalAll(node, lb))

	node, lb = buildCase(name, types, kind, boolValue)
	wf := ast.NewNodeFactory(ast.NodeFactoryHooks{})
	stmt := wf.NewExpressionStatement(node)
	block := wf.NewBlock(wf.NewNodeList([]*ast.Node{stmt}), true)
	lb[stmt] = "stmt"
	lb[block] = "block"
	ast.SetParentInChildren(block)
	fmt.Printf("tree\tn\t%s\n", evalAll(node, lb))
	var children []*ast.Node
	node.ForEachChild(func(c *ast.Node) bool {
		children = append(children, c)
		return false
	})
	for _, c := range children {
		fmt.Printf("tree\t%s\t%s\n", lb.of(c), evalAll(c, lb))
	}
}
